def require(condition, message):
    if not condition:
        raise ValueError(message)


def exact_cache_file(name, cache, roots, offline=False):
    """Use the fixed official URL; validate size, release pin and first-use lock."""
    expected = PUBLIC_SHA256[name]
    cache.mkdir(parents=True, exist_ok=True)
    receipt = cache / (name + '.sha256.json')
    if receipt.exists():
        local_pin = json.loads(receipt.read_text(encoding='utf-8'))['sha256']
        require(expected is None or local_pin == expected, 'Local/release file pin mismatch')
        expected = local_pin
    def validated(candidate):
        if candidate.stat().st_size != PUBLIC_SIZE[name]:
            return False
        actual = sha(candidate)
        if expected is not None and actual != expected:
            return False
        if name == COUNT_NAME:
            import h5py
            with h5py.File(candidate, 'r') as h:
                require('matrix' in h and 'barcodes' in h['matrix'], 'Invalid official H5 schema')
        if not receipt.exists():
            emit_json(receipt, dict(name=name, sha256=actual, bytes=PUBLIC_SIZE[name], locked_utc=utc_now(),
                policy='release_pin' if PUBLIC_SHA256[name] else 'first_complete_official_file_before_outcomes',
                publisher_supplied_checksum=False))
        return True
    path = cache / name
    if path.is_file():
        require(validated(path), 'Cached file size/hash mismatch: ' + str(path))
        return path
    for root in roots:
        if not root or not root.exists():
            continue
        for base, dirs, names in os.walk(root):
            dirs[:] = [d for d in dirs if d not in ('.git', '.venv', 'node_modules', '__pycache__')
                       and not d.startswith('paper3_stage2_results')]
            if name in names:
                found = Path(base) / name
                if validated(found):
                    print('REUSE', found, flush=True)
                    return found
    require(not offline, 'Offline: missing verified public file ' + name)
    url = DTANGLE_URL if name == DTANGLE_NAME else REMOTE_ROOT + name
    partial = path.with_name(name + '.partial')
    for attempt in range(12):
        try:
            offset = partial.stat().st_size if partial.exists() else 0
            headers = {'User-Agent': 'Paper3-reproducible-benchmark/2.0'}
            if offset:
                headers['Range'] = 'bytes=%d-' % offset
            request = urllib.request.Request(url, headers=headers)
            with urllib.request.urlopen(request, timeout=120) as source:
                append = source.status == 206 and offset > 0
                if append:
                    require(source.headers.get('Content-Range', '').startswith('bytes %d-' % offset),
                            'Invalid range response')
                expected_bytes = int(source.headers['Content-Length']) + (offset if append else 0) if source.headers.get('Content-Length') else None
                with partial.open('ab' if append else 'wb') as dst:
                    last_log = time.monotonic()
                    while chunk := source.read1(256 * 1024):
                        dst.write(chunk)
                        if time.monotonic() - last_log > 30:
                            print('DOWNLOAD_BYTES', name, dst.tell(), flush=True)
                            last_log = time.monotonic()
                if expected_bytes is not None and partial.stat().st_size != expected_bytes:
                    raise OSError('Truncated transfer; retained partial download for range retry')
            require(validated(partial), 'Downloaded public file differs from release/first-use pin or expected size: ' + name)
            os.replace(partial, path)
            print('DOWNLOADED', name, flush=True)
            return path
        except (OSError, urllib.error.URLError):
            if attempt == 11:
                raise
            time.sleep(min(15, 3 * (attempt + 1)))
    raise RuntimeError('Download failed: ' + name)


def external_metadata(path, min_cells=10):
    frame = pd.read_csv(path, dtype={'Barcode': str, 'SampleID': str})
    require({'Barcode', 'SampleID', 'Cell.Type', 'Diagnosis'} <= set(frame), 'External metadata schema changed')
    require(frame.Barcode.is_unique and frame.Barcode.notna().all(), 'Duplicate/missing external barcodes')
    require(frame.SampleID.notna().all(), 'Missing donor identifiers')
    require(set(frame['Cell.Type']) == set(CELL_MAP), 'External cell classes changed')
    frame['cell_id'] = frame.Barcode
    frame['donor_id'] = frame.SampleID
    frame['cell_type'] = frame['Cell.Type'].map(CELL_MAP)
    frame['source_id'] = SOURCE
    counts = pd.crosstab(frame.donor_id, frame.cell_type).reindex(columns=M.CT, fill_value=0)
    counts['eligible'] = counts.min(axis=1).ge(min_cells)
    counts['exclusion_reason'] = np.where(counts.eligible, '', 'fewer_than_%d_nuclei_in_at_least_one_frozen_class' % min_cells)
    eligible = counts.index[counts.eligible].tolist()
    require(len(eligible) >= 2, 'Fewer than two eligible external donor banks; no fallback resource is permitted')
    return frame, counts.reset_index(), eligible


def decode_h5(dataset):
    return dataset.asstr()[:]


def source_from_counts(label, genes, x, libs, meta):
    """Construct the same donor/class sufficient statistics as the frozen engine."""
    require(x.shape == (len(genes), len(meta)) and len(libs) == len(meta), 'External dimensions disagree')
    require(meta.cell_id.is_unique and (libs > 0).all(), 'Invalid cell identity/library size')
    donors = sorted(meta.donor_id.unique())
    nums, masses, ncells, masks, diagnostic = [], [], [], {}, []
    for donor in donors:
        pools = [np.flatnonzero(meta.donor_id.eq(donor) & meta.cell_type.eq(ct)) for ct in M.CT]
        require(min(map(len, pools)) >= 10, 'External donor lacks frozen class support')
        masks[donor] = pools
        nums.append(np.column_stack([np.asarray(x[:, p].sum(axis=1)).ravel() for p in pools]))
        masses.append(np.array([libs[p].sum() for p in pools]))
        ncells.append(np.array([len(p) for p in pools]))
        for ct, p in zip(M.CT, pools):
            diagnostic.append(dict(source=label, donor_id=donor, cell_type=ct, nuclei=len(p),
                                   recovered_counts=float(libs[p].sum()), mean_yield=float(libs[p].mean())))
    return dict(label=label, genes=np.array(genes), x=x.tocsc(), libs=libs,
                meta=meta.reset_index(drop=True), donors=donors, nums=np.array(nums),
                masses=np.array(masses), ncells=np.array(ncells), masks=masks, diagnostic=diagnostic)


def read_external(count_path, meta_path, active_genes, destination):
    import h5py
    meta, counts, eligible = external_metadata(meta_path)
    destination.mkdir(parents=True, exist_ok=True)
    emit_csv(destination / 'donor_class_eligibility.csv', counts)
    emit_csv(destination / 'class_mapping.csv', [{'author_class': k, 'frozen_class': v} for k, v in CELL_MAP.items()])
    with h5py.File(count_path, 'r') as h:
        g = h['matrix']
        barcode = pd.Index(decode_h5(g['barcodes']))
        native = decode_h5(g['features']['id'])
        # Only terminal Ensembl version numbers are removed; no symbol guessing.
        canonical = pd.Index([s.rsplit('.', 1)[0] if s.startswith('ENSG') and s.rsplit('.', 1)[-1].isdigit() else s for s in native])
        require(barcode.is_unique and canonical.is_unique, 'Ambiguous native external axis')
        require(meta.Barcode.isin(barcode).all(), 'Metadata barcodes missing from count file')
        all_x = sparse.csc_matrix((g['data'][:], g['indices'][:], g['indptr'][:]), shape=tuple(g['shape'][:]))
        if 'feature_type' in g['features']:
            types_ = decode_h5(g['features']['feature_type'])
            require(set(types_) == {'Gene Expression'}, 'Non-RNA features in external matrix')
    require(all_x.shape == (len(canonical), len(barcode)), 'Invalid 10x axes')
    require(np.isfinite(all_x.data).all() and (all_x.data >= 0).all()
            and np.equal(all_x.data, np.floor(all_x.data)).all(), 'External inputs are not nonnegative integer counts')
    all_x.sum_duplicates()
    meta = meta.loc[meta.donor_id.isin(eligible)].copy()
    positions = barcode.get_indexer(meta.Barcode)
    libs = np.asarray(all_x.sum(axis=0)).ravel()[positions]
    index = canonical.get_indexer(active_genes)
    present = index >= 0
    require(present.sum() >= 300, 'External annotation has insufficient active genes')
    rows = np.flatnonzero(present)
    values = all_x[index[present]][:, positions].tocoo()
    selected = sparse.csc_matrix((values.data, (rows[values.row], values.col)), shape=(len(active_genes), len(meta)))
    del all_x
    # Missing rows are storage placeholders ONLY; absent genes are excluded by annotation before any fit.
    out = source_from_counts(SOURCE, active_genes, selected, libs, meta)
    out['present'] = present
    emit_csv(destination / 'gene_annotation_presence.csv', pd.DataFrame({'gene_id': active_genes, 'present': present}))
    emit_csv(destination / 'donor_yields.csv', out['diagnostic'])
    emit_json(destination / 'preparation_receipt.json', dict(source=SOURCE, metadata_sha256=sha(meta_path),
        counts_sha256=sha(count_path), eligible_donors=eligible, retained_cells=len(meta),
        annotation_missing_active_genes=int((~present).sum()), processing='author_cellranger_aggr_integer_UMI',
        limits='PER.END is operationally mapped to EndoMural; not endothelial-only; original metadata labels not reclustered'))
    return out


DTANGLE_R = r'''
args <- commandArgs(trailingOnly=TRUE)
.libPaths(c(args[2], .libPaths()))
suppressPackageStartupMessages(library(dtangle))
stopifnot(as.character(packageVersion("dtangle")) == "2.0.9")
jobs <- read.csv(file.path(args[1], "jobs.csv"), stringsAsFactors=FALSE)
marks <- read.csv(file.path(args[1], "markers.csv"))
markers <- lapply(seq_len(7), function(k) marks$index[marks$cell_type == k])
errors <- list()
for (i in seq_len(nrow(jobs))) {
  key <- as.character(jobs$key[i])
  A <- as.matrix(read.csv(file.path(args[1], paste0(key, "_A.csv")), check.names=FALSE))
  Y <- as.matrix(read.csv(file.path(args[1], paste0(key, "_Y.csv")), check.names=FALSE))
  result <- tryCatch({
    fit <- dtangle(Y=log2(Y*1e6+1), references=log2(t(A)*1e6+1),
                   markers=markers, n_markers=lengths(markers), data_type="rna-seq")
    est <- as.matrix(fit$estimates)
    stopifnot(identical(dim(est), c(nrow(Y),7L)), all(is.finite(est)), all(est>=0),
              max(abs(rowSums(est)-1)) < 1e-5)
    list(est=est, reason="")
  }, error=function(e) list(est=matrix(NA_real_,nrow(Y),7), reason=conditionMessage(e)))
  write.table(result$est, file.path(args[1],paste0(key,"_out.csv")),
              sep=",",row.names=FALSE,col.names=FALSE,na="nan")
  errors[[i]] <- data.frame(key=key, reason=result$reason)
}
write.csv(do.call(rbind, errors), file.path(args[1],"errors.csv"),row.names=FALSE)
'''


def r_environment(library):
    env = dict(os.environ)
    env['R_LIBS_USER'] = str(library)
    return env


def check_r(args, cache, roots):
    executable = shutil.which(args.rscript)
    require(executable is not None, 'Rscript is required. Install R >=4.2 or pass --rscript /path/to/Rscript. No Python substitute is used.')
    library = cache / 'R_library'
    library.mkdir(parents=True, exist_ok=True)
    env = r_environment(library)
    check = cache / 'check_dtangle.R'
    check.write_text('.libPaths(c(commandArgs(TRUE)[1], .libPaths()))\n'
                     'if (!requireNamespace("dtangle", quietly=TRUE)) quit(status=2)\n'
                     'cat(as.character(packageVersion("dtangle")))\n', encoding='ascii')
    result = subprocess.run([executable, '--vanilla', str(check), str(library)], capture_output=True, text=True, env=env, timeout=90)
    if result.returncode != 0 or result.stdout.strip() != '2.0.9':
        require(args.install_r_package, 'Official dtangle 2.0.9 missing; rerun with --install-r-package (user-local R library).')
        tarball = exact_cache_file(DTANGLE_NAME, cache, roots, args.offline)
        command = '''args<-commandArgs(TRUE); options(timeout=180)
.libPaths(c(args[2], .libPaths()))
if (!requireNamespace("DEoptimR", quietly=TRUE)) {
  if (args[3]=="offline") stop("DEoptimR missing in offline mode; install it before running")
  install.packages("DEoptimR", repos="https://cloud.r-project.org", type="source", lib=args[2])
}
if (!requireNamespace("DEoptimR", quietly=TRUE)) stop("Failed to install required DEoptimR dependency")
install.packages(args[1], repos=NULL, type="source", lib=args[2])'''
        installer = cache / 'install_dtangle.R'
        installer.write_text(command + '\n', encoding='ascii')
        install = subprocess.run([executable, '--vanilla', str(installer), str(tarball), str(library),
                                  'offline' if args.offline else 'online'],
                                 capture_output=True, text=True, env=env, timeout=900)
        (cache / 'dtangle_install.log').write_text(install.stdout + install.stderr, encoding='utf-8')
        require(install.returncode == 0, 'Official R installation failed; see ' + str(cache / 'dtangle_install.log'))
    result = subprocess.run([executable, '--vanilla', str(check), str(library)], capture_output=True, text=True, env=env, timeout=90)
    require(result.returncode == 0 and result.stdout.strip() == '2.0.9',
            'Official dtangle 2.0.9 unavailable: ' + result.stdout[-500:] + result.stderr[-1000:])
    dependency = cache / 'check_DEoptimR.R'
    dependency.write_text('.libPaths(c(commandArgs(TRUE)[1], .libPaths()))\n'
                          'stopifnot(requireNamespace("DEoptimR", quietly=TRUE))\n'
                          'cat(as.character(packageVersion("DEoptimR")))\n', encoding='ascii')
    dep = subprocess.run([executable, '--vanilla', str(dependency), str(library)],
                         capture_output=True, text=True, env=env, timeout=60)
    require(dep.returncode == 0 and dep.stdout.strip(),
            'Cannot identify DEoptimR dependency: ' + dep.stdout[-500:] + dep.stderr[-1000:])
    return dict(executable=executable, library=str(library), version='2.0.9',
                DEoptimR_version=dep.stdout.strip(),
                source_sha256=PUBLIC_SHA256[DTANGLE_NAME], package_default_gamma=True,
                scope='official_estimator_on_reference_frozen_panel;not_a_complete_native_marker_workflow')


def official_batch(pending, job, r_info):
    work = Path(r_info['library']).parent / 'bridge_work'
    work.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix='dtangle_', dir=work, ignore_cleanup_errors=True) as tmp:
        folder = Path(tmp)
        (folder / 'bridge.R').write_text(DTANGLE_R, encoding='ascii')
        E.official_markers(job).to_csv(folder / 'markers.csv', index=False)
        pd.DataFrame({'key': [str(i) for i, _ in pending]}).to_csv(folder / 'jobs.csv', index=False)
        for rep, data in pending:
            pd.DataFrame(data['A']).to_csv(folder / (str(rep) + '_A.csv'), index=False)
            pd.DataFrame(data['mixture']).to_csv(folder / (str(rep) + '_Y.csv'), index=False)
        proc = subprocess.run([r_info['executable'], '--vanilla', str(folder / 'bridge.R'), str(folder), r_info['library']],
                              env=r_environment(Path(r_info['library'])), capture_output=True, text=True, timeout=900)
        require(proc.returncode == 0, 'Official dtangle bridge failed: ' + proc.stderr[-3000:])
        errors = pd.read_csv(folder / 'errors.csv', keep_default_na=False, dtype={'key': str}).set_index('key').reason
        answers = []
        for rep, data in pending:
            prediction = np.loadtxt(folder / (str(rep) + '_out.csv'), delimiter=',', ndmin=2)
            require(prediction.shape == data['p'].shape, 'Official returned wrong prediction shape')
            answers.append((rep, data, prediction, errors.loc[str(rep)]))
        return answers


def resampled_fit(data, props, indices):
    """Refit coefficients, not unused HC3 standard errors, within bootstrap draws."""
    outcome, group, p = data['y'][indices], data['group'][indices], props[indices]
    failed = np.full(outcome.shape[1], np.nan)
    if not np.isfinite(p).all() or len(np.unique(group)) != 2:
        return failed
    u, singular, _ = np.linalg.svd(p-p.mean(axis=0), full_matrices=False)
    if (singular > max(singular[0]*1e-10, 1e-12)).sum() < 6:
        return failed
    design = np.column_stack([np.ones(len(group)), group, u[:, :6]*np.sqrt(len(group)-1)])
    if np.linalg.matrix_rank(design) != design.shape[1]:
        return failed
    return (np.linalg.pinv(design) @ outcome)[1]


def bootstrap_plan(data, case, rep, options):
    n = len(data['group'])
    observed_w = np.array([int(x) for x in data['allocation'].split(';')])
    require(observed_w.sum() == 4, 'Expected four reference donor draws')
    rng = M.rng_for(options['bootstrap_seed'], 'joint_reference_and_mixture_bootstrap',
                    case['reference_source'], case['target_source'], case['target_donor'], case['n'], rep)
    groups = [np.flatnonzero(data['group'] == g) for g in (0, 1)]
    result = []
    for _ in range(options['bootstrap_draws']):
        rows = np.arange(n)
        for index in groups:
            rows[index] = rng.choice(index, len(index), replace=True)
        # Reference donors absent from the observed resample cannot reappear in its bootstrap.
        weights = rng.multinomial(4, observed_w / 4)
        result.append((rows, weights))
    return result


def bootstrap_se_fit(point, betas, draws, min_success):
    out = copy.deepcopy(point)
    values = np.asarray(betas, float)
    finite = np.isfinite(values)
    successes = finite.sum(axis=0)
    means = E.count_mean(values)
    variance = np.divide(np.nansum((values - means)**2, axis=0), successes-1,
                         out=np.full(values.shape[1], np.nan), where=successes > 1)
    se = np.sqrt(variance)
    required = max(2, int(math.ceil(draws * min_success)))
    out['se'] = se
    out['good'] = point['good'] & (successes >= required) & np.isfinite(se) & (se > 1e-12)
    if not out['good'].all():
        out['reason'] = (point['reason'] + '; insufficient_bootstrap_support_or_variance').strip('; ')
    return out, successes / draws


def uncertainty_fits(job, data, point_props, point_fit, case, rep, options):
    n_genes = len(data['truth'])
    b = options['bootstrap_draws']
    arrays = {key: np.full((b, n_genes), np.nan) for key in ('fixed', 'joint')}
    reference_cache = {}
    if point_fit['basic']:
        for j, (indices, weights) in enumerate(bootstrap_plan(data, case, rep, options)):
            arrays['fixed'][j] = resampled_fit(data, point_props, indices)
            key = tuple(weights.tolist())
            if key not in reference_cache:
                ref = M.reference(job['source'], job['refs'], weights)
                q, _, _ = E.repaired_prediction(ref['A'][job['panels']['balanced']], data['mixture'], 'drop_zero_weighted')
                reference_cache[key] = E.convert_available_rows(q, ref['pooled_yield'])
            arrays['joint'][j] = resampled_fit(data, reference_cache[key], indices)
    result = {}
    for label in ('fixed', 'joint'):
        fit, fraction = bootstrap_se_fit(point_fit, arrays[label], b, options['min_bootstrap_success'])
        result[label] = (fit, dict(bootstrap_planned=b, bootstrap_success_fraction=float(fraction.mean()),
                                  bootstrap_min_gene_success_fraction=float(fraction.min()),
                                  unique_reference_bootstrap_allocations=len(reference_cache)))
    return result


def make_external_jobs(jobs, external, output):
    (output / 'external').mkdir(parents=True, exist_ok=True)
    new_jobs, exclusions = [], []
    for old in jobs:
        if old['split'] != 0:
            continue
        job = dict(old)
        old_markers, old_tests = old['panels']['balanced'], old['test']
        ix = old_markers[external['present'][old_markers]]
        test = old_tests[external['present'][old_tests]]
        require(len(ix) >= 210 and len(test) >= 80, 'External annotation overlap below locked 70% marker / 80% test threshold')
        alt_set = set(old_tests[:20].tolist())
        job.update(target_source=external, targets=external['donors'], test=test,
                   panels={'balanced': ix}, alt_mask=np.array([g in alt_set for g in test]))
        require(job['alt_mask'].any(), 'No externally measured frozen alternative genes')
        # No external expression, outcome, RMSE or significance enters panel construction.
        E.official_markers(job)
        new_jobs.append(job)
        for kind, original, retained in (('marker', old_markers, ix), ('test', old_tests, test)):
            for index in original:
                exclusions.append(dict(reference_source=old['source']['label'], role=kind,
                    gene_id=old['source']['genes'][index], included=bool(index in retained),
                    reason='' if index in retained else 'absent_from_external_annotation_not_zero_expression'))
    emit_csv(output / 'external' / 'frozen_gene_eligibility.csv', exclusions)
    return new_jobs


def external_repetition(job, case, rep, options):
    reference, target = job['source'], job['target_source']
    base = M.reference(reference, job['refs'])
    key = [SOURCE, reference['label'], job['split'], case['target_donor'], case['n'], rep]
    rng = M.rng_for(options['external_seed'], 'locked_external_design', key)
    group = np.repeat([0., 1.], case['n'] // 2)
    rng.shuffle(group)
    weights = rng.multinomial(4, np.full(4, .25))
    ref = M.reference(reference, job['refs'], weights)
    p = rng.dirichlet(M.concentration(base, 'reference_anchored'), case['n'])
    p[:, 0] *= np.exp(group * case['composition_shift'])
    p = M.normalize(p)
    draw = M.empirical_draw(target, case['target_donor'], p, options['nuclei'],
                             M.rng_for(options['external_seed'], 'locked_external_counts', key))
    test, ix = job['test'], job['panels']['balanced']
    ref_scale = base['mean_counts'].mean(axis=1)[test]
    require((ref_scale > 0).all(), 'Frozen reference test scale is zero')
    truth = job['alt_mask'].astype(float) * case['effect']
    expected = group[:, None] * options['nuclei'] * ref_scale[None, :] * truth
    observed = draw['counts'].copy()
    observed[:, test] += M.rng_for(options['external_seed'], 'locked_external_spike', key).poisson(expected)
    y = observed[:, test] / (options['nuclei'] * ref_scale)
    donor = target['donors'].index(case['target_donor'])
    mu = target['nums'][donor] / target['ncells'][donor]
    nuisance = (draw['cell_truth'] @ mu[test].T) / ref_scale
    noise = y - nuisance - group[:, None] * truth
    total = draw['mass'].sum(axis=1) + (observed - draw['counts']).sum(axis=1)
    return dict(y=y, group=group, truth=truth, nuisance=nuisance, noise=noise,
                p=draw['cell_truth'], ref=ref, A=ref['A'][ix], mixture=observed[:, ix]/total[:, None],
                allocation=';'.join(map(str, weights)))


def paired_comparisons(frame):
    pairs = [('dtangle_official', 'drop_zero_weighted'), ('drop_zero_weighted', 'weighted_original'),
             ('unweighted', 'drop_zero_weighted'), (BOOT_METHODS[0], 'drop_zero_weighted'),
             (BOOT_METHODS[1], 'drop_zero_weighted'), (BOOT_METHODS[1], BOOT_METHODS[0])]
    rows = []
    for (scale, gate), group in frame.groupby(['scale', 'gate'], sort=True):
        for a, b in pairs:
            left = group[group.method.eq(a)].set_index('rep')
            right = group[group.method.eq(b)].set_index('rep')
            if left.empty or right.empty:
                continue
            require(left.index.equals(right.index), 'Method comparison has unpaired repetitions')
            common = left.complete_fit.eq(1) & right.complete_fit.eq(1)
            restored = left.complete_fit.eq(1) & right.complete_fit.eq(0)
            for metric in ('availability', 'fdp', 'any_false', 'power', 'delivered_coverage',
                           'coverage', 'gene_error_mean', 'proportion_rmse'):
                all_planned = metric in ('availability', 'fdp', 'any_false', 'power', 'delivered_coverage')
                subset = pd.Series(True, index=left.index) if all_planned else common
                delta = (left.loc[subset, metric] - right.loc[subset, metric]).dropna()
                mean, se = M.finite_mean(delta), E.sem(delta)
                rows.append(dict(method_a=a, method_b=b, scale=scale, gate=gate, metric=metric,
                    delta=mean, paired_mcse=se, mc_low=mean-1.96*se, mc_high=mean+1.96*se,
                    planned_replicates=len(left), paired_replicates=len(delta),
                    common_complete_fits=int(common.sum()), restored_complete_fits=int(restored.sum()),
                    denominator='all_planned_replicates' if all_planned else 'common_complete_fits',
                    interval_scope='Monte_Carlo_conditional_fixed_banks'))
    return pd.DataFrame(rows)


def scenario_data(job, case, rep, options):
    if case['module'] == 'external':
        return external_repetition(job, case, rep, options)
    old_case = dict(case, module='counts')
    return E.generate_repetition(job, old_case, rep, dict(options, seed=options['paired_seed']))


def add_bootstrap(audit, rep, job, case, data, props, options, diag):
    point = M.model_fit(data['y'], data['group'], props, data['nuisance'], data['noise'], data['truth'])
    measures = M.prop_diagnostics(props, data['p'], data['group'])
    defaults = dict(diag, **measures, allocation=data['allocation'])
    for label, (fit, extra) in uncertainty_fits(job, data, props, point, case, rep, options).items():
        method = BOOT_METHODS[0] if label == 'fixed' else BOOT_METHODS[1]
        audit.add(rep, method, PRIMARY_SCALE, fit, dict(defaults, **extra))


def case_replicates(case, options):
    return options[{'compare': 'compare_replicates', 'uncertainty': 'uncertainty_replicates',
                    'external': 'external_replicates'}[case['module']]]


def run_case(case):
    options = OPTIONS
    job = JOBS[case['job_index']]
    output = Path(options['output']) / 'cases' / case['case_id']
    output.mkdir(parents=True, exist_ok=True)
    complete = output / 'complete.json'
    if complete.exists():
        old = json.loads(complete.read_text(encoding='utf-8'))
        require(old['run_signature'] == options['run_signature'], 'Checkpoint protocol mismatch')
        for name, digest in old['files'].items():
            require(sha(output / name) == digest, 'Damaged checkpoint ' + str(output / name))
        print('RESUME', case['case_id'], flush=True)
        return case['case_id']
    print('START', case['case_id'], case['reference_source'], case['target_donor'], flush=True)
    audit, pending = None, []
    repetitions = case_replicates(case, options)
    for rep in range(repetitions):
        data = scenario_data(job, case, rep, options)
        if audit is None:
            audit = E.CaseAudit(data['truth'], job['source']['genes'][job['test']])
        E.fit_prediction(audit, rep, 'oracle', 'cell_fraction', data['p'], data)
        E.fit_prediction(audit, rep, 'unadjusted', 'none', None, data)
        predictions = {}
        methods = E.METHODS if case['module'] != 'uncertainty' else ['drop_zero_weighted']
        has_zero = (data['A'].mean(axis=1) <= 0).any()
        for method in methods:
            alias = 'weighted_original' if method == 'drop_zero_weighted' and not has_zero and 'weighted_original' in predictions else None
            if method == 'zero_fallback_unweighted':
                alias = 'unweighted' if has_zero else 'weighted_original'
            if alias is None:
                q, reason, diag = E.repaired_prediction(data['A'], data['mixture'], method)
            else:
                q, reason, diag = predictions[alias]
            predictions[method] = q, reason, diag
            props = E.convert_available_rows(q, data['ref']['pooled_yield'])
            E.fit_prediction(audit, rep, method, PRIMARY_SCALE, props, data, reason, diag)
            if method == 'drop_zero_weighted' and case['module'] in ('uncertainty', 'external'):
                add_bootstrap(audit, rep, job, case, data, props, options, diag)
        if case['module'] in ('compare', 'external'):
            pending.append((rep, data))
            if len(pending) == 20 or rep == repetitions-1:
                for i, d, q, reason in official_batch(pending, job, options['official']):
                    props = E.convert_available_rows(q, d['ref']['pooled_yield'])
                    positive = d['A'].mean(axis=1) > 0
                    diag = dict(zero_rows=int((~positive).sum()), retained_rows=int(positive.sum()))
                    E.fit_prediction(audit, i, 'dtangle_official', PRIMARY_SCALE, props, d, reason, diag)
                pending.clear()
        if (rep+1) % 20 == 0:
            print('PROGRESS', case['case_id'], rep+1, '/', repetitions, flush=True)
    summary, genes, replicates, _ = audit.finish()
    if 'bootstrap_success_fraction' in replicates:
        boot = replicates.groupby(['method', 'scale', 'gate'], as_index=False)[[
            'bootstrap_success_fraction', 'bootstrap_min_gene_success_fraction']].mean()
        summary = summary.merge(boot, on=['method', 'scale', 'gate'], validate='one_to_one')
    tables = {'summary.csv': summary, 'per_gene.csv': genes, 'replicates.csv': replicates,
              'paired.csv': paired_comparisons(replicates)}
    for name, frame in tables.items():
        for key, value in reversed(list(case.items())):
            frame.insert(0, key, value)
        emit_csv(output / name, frame)
    emit_json(complete, dict(run_signature=options['run_signature'], case=case,
        files={name: sha(output / name) for name in tables}, finished_utc=utc_now()))
    print('DONE', case['case_id'], flush=True)
    return case['case_id']


def plan_cases(jobs, modules, options):
    cases = []
    for job_index, job in enumerate(jobs):
        external = 'target_source' in job
        if job['split'] != 0:
            continue
        targets = job['targets'][:1] if options['profile'] == 'smoke' else job['targets']
        for module in modules:
            if module == 'report' or (external != (module == 'external')):
                continue
            shifts = [1.] if module in ('uncertainty', 'external') else [0., 1.]
            for donor, n, shift, effect in itertools.product(targets, options['n_grid'], shifts, [0., .5]):
                case = dict(job_index=job_index, module=module, reference_source=job['source']['label'],
                    target_source=SOURCE if external else job['source']['label'], split=job['split'],
                    target_donor=donor, n=n, composition_shift=shift, profile_mismatch=-1., effect=effect,
                    planned_genes=len(job['test']), retained_markers=len(job['panels']['balanced']))
                case['case_id'] = module + '_' + M.digest(case)[:16]
                cases.append(case)
    require(len({c['case_id'] for c in cases}) == len(cases), 'Duplicate planned cases')
    return cases


def source_equal_summary(summary):
    keys = ['module', 'reference_source', 'target_source', 'n', 'composition_shift',
            'effect', 'method', 'scale', 'gate']
    metrics = ['availability', 'coverage', 'fdp', 'any_false', 'power', 'power_complete_fits',
               'delivered_coverage', 'mean_absolute_bias', 'mean_absolute_nuisance_bias',
               'empirical_sd', 'mean_se', 'rms_se', 'proportion_rmse']
    donors = summary.groupby(keys + ['target_donor'], as_index=False)[metrics].mean()
    equal = donors.groupby(keys, as_index=False)[metrics].mean()
    counts = donors.groupby(keys, as_index=False).target_donor.nunique().rename(columns={'target_donor': 'n_target_donors'})
    equal = equal.merge(counts, on=keys, validate='one_to_one')
    equal['weighting'] = 'equal_target_donor;reference_sources_kept_separate'
    return donors, equal


def pareto_frontier(equal):
    frame = equal.copy()
    frame['coverage_distance_from_095'] = abs(frame.coverage-.95)
    frame['descriptive_nondominated'] = False
    frame['not_a_validated_selection_rule'] = True
    keys = ['module', 'reference_source', 'target_source', 'n', 'composition_shift', 'effect']
    for _, group in frame.groupby(keys, sort=True):
        # Oracle is a diagnostic upper reference, not a selectable empirical method.
        subset = group[~group.method.isin(['oracle', 'unadjusted']) & group.scale.eq(PRIMARY_SCALE)]
        objectives = pd.DataFrame({'availability_cost': -subset.availability,
            'FDR_cost': subset.fdp, 'coverage_cost': subset.coverage_distance_from_095})
        if len(subset) and subset.effect.iloc[0] > 0:
            objectives['power_cost'] = -subset.power
        valid = np.isfinite(objectives).all(axis=1)
        positions = objectives.index[valid]
        a = objectives.loc[valid].to_numpy()
        for i, index in enumerate(positions):
            dominates = (a <= a[i]+1e-12).all(axis=1) & (a < a[i]-1e-12).any(axis=1)
            frame.loc[index, 'descriptive_nondominated'] = not dominates.any()
    return frame


def write_reporting_tools(output):
    benchmark = [
        ('estimand', 'State the adjusted expression coefficient and known injected effect, not cell-type-specific disease expression.'),
        ('bias', 'Per gene, report coefficient bias and FWL composition/noise projections over available fits.'),
        ('uncertainty', 'Report empirical SD, estimated SE, interval width, and conditional coverage.'),
        ('availability', 'Report available tests / planned tests and all failure reasons; do not delete failures.'),
        ('FDR', 'Use all planned repetitions; failed tests remain p=1 in the complete planned BH family.'),
        ('power', 'Report both all-planned power and power conditional on complete fits.'),
        ('paired', 'Pair mixtures, group labels, reference resamples, injected effects, and noise across methods.'),
        ('support', 'Report reference zero rows, retained rank, bootstrap success, and donor eligibility.'),
        ('units', 'Mixtures are not patients; report unique donors separately from Monte Carlo repetitions.'),
        ('selection', 'Frontiers describe trade-offs; any selection threshold requires independent evaluation.'),
    ]
    real = [
        ('truth_unavailable', 'Do not report unknown real-data bias or coverage as if observed.'),
        ('reference_support', 'Report reference donors, zero rows, class support, and estimation failures.'),
        ('sensitivity', 'Report sensitivity to reference, marker panel, model, and operational cell-class mapping.'),
        ('uncertainty_scope', 'State which reference and sampling uncertainty is propagated, and which is not.'),
        ('group_context', 'Do not infer therapeutic activation/inhibition or causal disease effects from this benchmark.'),
        ('decision_scope', 'Stable results are not proof of calibration; avoid a universal pass/fail safety threshold.'),
    ]
    emit_csv(output / 'benchmark_reporting_checklist.csv', pd.DataFrame(benchmark, columns=['item', 'requirement']))
    emit_csv(output / 'real_data_reporting_checklist.csv', pd.DataFrame(real, columns=['item', 'requirement']))


def draw_reports(equal, output):
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    methods = ['weighted_original', 'drop_zero_weighted', 'unweighted', 'dtangle_official', *BOOT_METHODS, 'oracle']
    colors = dict(zip(methods, ['#8b8b8b', '#1779ad', '#d08020', '#23835d', '#7856a6', '#c6484c', '#222222']))
    part = equal[equal.gate.eq('basic') & equal.composition_shift.eq(1) & equal.effect.eq(0)]
    for module, group in part.groupby('module'):
        group = group[group.method.isin(methods)]
        emit_csv(output / (module + '_availability_coverage_plot_data.csv'), group)
        sources = sorted(group.reference_source.unique())
        fig, axes = plt.subplots(1, len(sources), figsize=(6*len(sources), 4.8), squeeze=False)
        for ax, source in zip(axes[0], sources):
            for row in group[group.reference_source.eq(source)].itertuples():
                if not np.isfinite(row.coverage):
                    continue
                ax.scatter(row.availability*100, row.coverage*100, color=colors.get(row.method, '#333333'),
                           marker='o' if row.n == 20 else '^', s=52, alpha=.85)
            ax.axhline(95, color='#444444', linestyle='--', linewidth=1)
            ax.set(xlabel='Available planned tests (%)', ylabel='Coverage among available intervals (%)',
                   title=source + ' reference', xlim=(-2, 102), ylim=(-2, 102))
            ax.grid(alpha=.18)
        from matplotlib.lines import Line2D
        present = [x for x in methods if x in set(group.method)]
        names = {'weighted_original':'Original weighted NNLS', 'drop_zero_weighted':'Drop-zero weighted NNLS',
                 'unweighted':'Unweighted NNLS', 'dtangle_official':'Official dtangle',
                 BOOT_METHODS[0]:'Fixed-proportion bootstrap', BOOT_METHODS[1]:'Joint-reference bootstrap',
                 'oracle':'Oracle fractions'}
        handles = [Line2D([], [], marker='o', linestyle='', color=colors[x], label=names[x]) for x in present]
        fig.legend(handles=handles, loc='lower center', bbox_to_anchor=(.5, .075), ncol=2, fontsize=8, frameon=False)
        fig.suptitle(module + ': paired calibration and availability (null, shift=1)')
        fig.text(.5, .025, 'Circles: n=20; triangles: other n.\nDonor-equal descriptive means; not independent patient experiments.',
                 fontsize=8, ha='center')
        fig.tight_layout(rect=(0, .30, 1, .93))
        fig.savefig(output / (module + '_availability_coverage.png'), dpi=180, bbox_inches='tight')
        fig.savefig(output / (module + '_availability_coverage.pdf'), bbox_inches='tight')
        plt.close(fig)


def audit_previous(previous, output):
    if not previous or not previous.exists():
        return dict(status='not_supplied;new_experiments_do_not_require_old_result_files')
    protocol = json.loads((previous / 'protocol.json').read_text(encoding='utf-8'))
    status = json.loads((previous / 'RUN_STATUS.json').read_text(encoding='utf-8'))
    expected = 'd3450a8a45b890065b90f3246b96d876ba33775f66a744c915ce8093a2ef8e35'
    require(protocol['run_signature'] == expected and status['run_signature'] == expected,
            'Previous directory is not the reviewed 864-case run; omit --previous-results or select the reviewed run')
    pieces = []
    for folder in sorted((previous / 'cases').iterdir()):
        if not folder.is_dir():
            continue
        receipt = json.loads((folder / 'complete.json').read_text(encoding='utf-8'))
        require(receipt['run_signature'] == expected, 'Mixed previous protocols')
        require(sha(folder / 'summary.csv') == receipt['files']['summary.csv'], 'Previous summary hash mismatch')
        pieces.append(pd.read_csv(folder / 'summary.csv'))
    require(len(pieces) == 864, 'Previous run is incomplete')
    emit_csv(output / 'previous_v1_summary_NOT_POOLED.csv', pd.concat(pieces, ignore_index=True))
    return dict(status='864_case_summaries_verified_and_copied;not_pooled_with_new_protocol', run_signature=expected)


def make_report(output, plan, protocol, previous=None):
    summaries, genes, pairs, failures = [], [], [], []
    missing = []
    for case in plan:
        folder = output / 'cases' / case['case_id']
        if not (folder / 'complete.json').exists():
            missing.append(case['case_id'])
            continue
        receipt = json.loads((folder / 'complete.json').read_text(encoding='utf-8'))
        require(receipt['run_signature'] == protocol['run_signature'], 'Mixed completed protocols')
        for name, digest in receipt['files'].items():
            require(sha(folder / name) == digest, 'Corrupt report input: ' + str(folder / name))
        summaries.append(pd.read_csv(folder / 'summary.csv'))
        genes.append(pd.read_csv(folder / 'per_gene.csv'))
        pairs.append(pd.read_csv(folder / 'paired.csv'))
        records = pd.read_csv(folder / 'replicates.csv', keep_default_na=True)
        records['reason'] = records.reason.fillna('')
        bad = records[records.available_tests.lt(records.planned_tests)]
        keys = ['module', 'reference_source', 'target_source', 'target_donor', 'n', 'effect', 'method', 'gate', 'reason']
        failures.append(bad.groupby(keys, dropna=False).size().reset_index(name='unavailable_repetitions'))
    require(summaries, 'No completed cases available for reporting')
    combined = pd.concat(summaries, ignore_index=True)
    emit_csv(output / 'all_scenario_summary.csv', combined)
    emit_csv(output / 'all_per_gene.csv', pd.concat(genes, ignore_index=True))
    emit_csv(output / 'paired_contrasts.csv', pd.concat(pairs, ignore_index=True))
    emit_csv(output / 'failure_reasons.csv', pd.concat(failures, ignore_index=True))
    donors, equal = source_equal_summary(combined)
    emit_csv(output / 'donor_summary.csv', donors)
    emit_csv(output / 'donor_equal_summary.csv', equal)
    emit_csv(output / 'descriptive_tradeoff_frontier.csv', pareto_frontier(equal))
    write_reporting_tools(output)
    draw_reports(equal, output)
    old = audit_previous(previous, output)
    scope = protocol['settings']['profile']
    status = 'COMPLETE_FOR_LOCKED_PLAN' if not missing and scope == 'full' else 'INCOMPLETE_OR_SMOKE_ONLY'
    lines = [
        '# Paper 3 stage-2 result report', '',
        'Status: **' + status + '**', '',
        'Protocol: `' + protocol['run_signature'] + '`',
        'Completed cases: %d / %d.' % (len(summaries), len(plan)), '',
        '## Scope and interpretation',
        '- Official dtangle 2.0.9 is run on the same frozen/reference-defined panel with its RNA-seq gamma default. This is an official-estimator comparison, not a claim to reproduce its full original benchmark.',
        '- Bootstrap arms retain the SAME point coefficient. Fixed-pairs resampling estimates mixture sampling uncertainty; joint resampling also re-estimates one shared reference for all mixtures in that draw.',
        '- Four observed reference donor draws are resampled as donors. Target mixtures are stratified-resampled within one FIXED target donor bank, not treated as independent patients.',
        '- Bootstrap SD enters the same t-reference Wald interval (df=n-8) as the plugin comparison. This is a candidate uncertainty propagation procedure being evaluated, not guaranteed valid inference or official DECALS.',
        '- Bootstrap draws with rank/support failure are recorded, not retried until success. Required valid-draw fraction per gene: %g (locked setting).' % protocol['settings'].get('min_bootstrap_success', .95),
        '- Coverage uses available gene intervals. FDR/power use all planned repetitions; unavailable tests retain p=1 in the planned BH family.',
        '- Donor-equal summaries keep reference sources separate. Monte Carlo intervals quantify repetition variability conditional on banks, not a population of patients.',
        '- The external source is GSE174367, using author-provided annotated integer UMI counts after cellranger aggr. Groups/effects in this benchmark are generated; this is NOT an AD-versus-control differential-expression validation.',
        '- External cell classes are operational mappings, particularly PER.END to EndoMural. Selection is by annotation availability and >=10 cells/class/donor, not analysis outcomes.',
        '- The new source is absent from the frozen two-resource Paper3 inputs; donor independence across studies is not genetically certified. Disclose any other prior use in development.',
        '- The external protocol is frozen before benchmark outcomes, but this local timestamp is not a public preregistration.',
        '- Trade-off frontiers are descriptive. No optimal threshold or general safety rule is selected from these same evaluation outcomes.', '',
        '## Important result files',
        '- `donor_equal_summary.csv`: source-specific, target-donor-equal results.',
        '- `all_per_gene.csv`: bias, FWL projections, SD/SE, coverage, and widths.',
        '- `paired_contrasts.csv`: all-planned and common-success contrasts with explicit denominators.',
        '- `failure_reasons.csv`: failures and abstention, retained in the audit.',
        '- `descriptive_tradeoff_frontier.csv`: calibration/availability/power trade-offs, not a validated selection rule.',
        '- `benchmark_reporting_checklist.csv` and `real_data_reporting_checklist.csv`: separate truth-aware and real-data requirements.',
        '- `external/`: original file hashes, operational class map, donor eligibility, gene availability.', '',
        '## Previous run', json.dumps(old, ensure_ascii=False), '',
        '## Boundaries',
        'No global claim that every repair fails, mismatch always harms inference, or strict screening is universally ineffective is generated.',
        'Reference yield transport, sparse class support, shared reference errors, and empirical-bank limitations remain explicit.',
        'Publication claims must follow the actual CSV results, including null/negative and successful-repair scenarios.',
    ]
    (output / 'REPORT.md').write_text('\n'.join(lines) + '\n', encoding='utf-8')
    emit_json(output / 'report_audit.json', dict(status=status, completed_cases=len(summaries),
        planned_cases=len(plan), missing_cases=missing, previous=old, created_utc=utc_now()))
    return status


def synthetic_job(seed=47):
    rng = np.random.default_rng(seed)
    genes = np.array(['ENSG%011d' % (i+1) for i in range(420)])
    owner = np.arange(len(genes)) % 7
    records, columns = [], []
    for donor in range(6):
        for ct in range(7):
            for cell in range(12):
                rate = .3 + (owner == ct)*5
                columns.append(rng.poisson(rate * rng.lognormal(0, .2)))
                records.append(dict(cell_id='d%d_c%d_%d' % (donor, ct, cell), donor_id='d%d' % donor,
                                    cell_type=M.CT[ct], source_id='synthetic'))
    x = sparse.csc_matrix(np.array(columns).T)
    libs = np.asarray(x.sum(axis=0)).ravel().astype(float) + 100
    source = source_from_counts('SYNTHETIC', genes, x, libs, pd.DataFrame(records))
    return dict(source=source, refs=source['donors'][:4], targets=source['donors'][4:], split=0,
                test=np.arange(300, 400), panels={'balanced': np.arange(300)})


def self_test(destination=None):
    global JOBS, OPTIONS
    job = synthetic_job()
    options = dict(profile='smoke', n_grid=[20], compare_replicates=2, uncertainty_replicates=3,
        external_replicates=2, bootstrap_draws=19, min_bootstrap_success=.95, nuclei=200,
        paired_seed=2026101103, bootstrap_seed=2026101117, external_seed=2026101119,
        seed=2026101103, run_signature='SYNTHETIC_SOFTWARE_TEST_ONLY')
    cases = plan_cases([job], ['uncertainty'], options)
    data = scenario_data(job, cases[0], 0, options)
    q, _, _ = E.repaired_prediction(data['A'], data['mixture'], 'drop_zero_weighted')
    props = E.convert_available_rows(q, data['ref']['pooled_yield'])
    point = M.model_fit(data['y'], data['group'], props, data['nuisance'], data['noise'], data['truth'])
    require(point['basic'], 'Synthetic coefficient fit failed')
    plan = bootstrap_plan(data, cases[0], 0, options)
    observed = np.array([int(v) for v in data['allocation'].split(';')])
    for indices, weights in plan:
        require(np.array_equal(data['group'], data['group'][indices]), 'Group-stratified resampling failed')
        require(not weights[observed == 0].any() and weights.sum() == 4, 'Reference resampling escaped the observed sample')
    boot = uncertainty_fits(job, data, props, point, cases[0], 0, options)
    require(all(np.array_equal(fit['beta'], point['beta']) for fit, _ in boot.values()), 'Bootstrap changed point coefficient')
    failed, frac = bootstrap_se_fit(point, np.full((19,100), np.nan), 19, .95)
    require(not failed['good'].any() and (frac == 0).all(), 'Bootstrap failures were not retained')
    context = nullcontext(str(destination)) if destination else tempfile.TemporaryDirectory(
        prefix='paper3_stage2_selftest_', dir=Path.cwd(), ignore_cleanup_errors=True)
    with context as temp:
        output = Path(destination).resolve() if destination else Path(temp)
        output.mkdir(parents=True, exist_ok=True)
        OPTIONS, JOBS = dict(options, output=str(output)), [job]
        for case in cases:
            run_case(case)
            run_case(case)
        for case in cases:
            folder = output / 'cases' / case['case_id']
            f = pd.read_csv(folder / 'replicates.csv')
            require(f.planned_tests.eq(100).all() and f.rep.nunique() == 3, 'Incorrect planned denominator')
            require(f.discoveries.ge(f.false_discoveries).all(), 'Invalid discoveries')
            require(f.availability.between(0,1).all(), 'Invalid availability')
        emit_json(output / 'SELF_TEST.json', dict(status='passed', scientific_validation=False,
            checks=['paired_seed', 'group_stratification', 'reference_support', 'unchanged_point_estimate',
                    'failure_denominator', 'FWL_identity', 'case_output', 'resume_hash_verification']))
    print('SELF-TEST PASS: synthetic software tests only; no real-data validation was performed.', flush=True)


def parser():
    p = argparse.ArgumentParser(description='Paper3: official comparator, shared-reference uncertainty, reporting, one external source.')
    p.add_argument('--setup-python', action='store_true', help='Create/reuse a private Python venv and install dependencies before loading this standalone script; does not install R.')
    p.add_argument('--project-root', type=Path, default=Path('/home/research/git/repository/paper1_public_evidence'))
    p.add_argument('--output', type=Path)
    p.add_argument('--modules', default='compare,uncertainty,external,report')
    p.add_argument('--workers', type=int, default=8)
    p.add_argument('--libd-dir', type=Path)
    p.add_argument('--seaad-dir', type=Path)
    p.add_argument('--gene-map', type=Path)
    p.add_argument('--external-cache', type=Path, help='Directory with the original two named GEO files; reused only if hashes match.')
    p.add_argument('--previous-results', type=Path)
    p.add_argument('--rscript', default='Rscript')
    p.add_argument('--install-r-package', action='store_true', help='Install pinned official dtangle into a private R library if missing.')
    p.add_argument('--offline', action='store_true')
    p.add_argument('--smoke', action='store_true', help='Real-data execution check only; not a publication run.')
    p.add_argument('--compare-replicates', type=int, default=400)
    p.add_argument('--uncertainty-replicates', type=int, default=200)
    p.add_argument('--external-replicates', type=int, default=200)
    p.add_argument('--bootstrap-draws', type=int, default=199)
    p.add_argument('--min-bootstrap-success', type=float, default=.95)
    p.add_argument('--report-only', action='store_true')
    p.add_argument('--preflight', action='store_true', help='Check source hashes, public inputs and R; do not run simulations.')
    p.add_argument('--self-test', action='store_true')
    p.add_argument('--self-test-output', type=Path)
    return p


def main():
    global JOBS, OPTIONS
    args = parser().parse_args()
    if args.self_test:
        self_test(args.self_test_output)
        return 0
    root = args.project_root.expanduser().resolve()
    output = (args.output or root / ('paper3_stage2_results_smoke' if args.smoke else 'paper3_stage2_results_v2')).expanduser().resolve()
    output.mkdir(parents=True, exist_ok=True)
    E.hold_output_lock(output)
    if args.report_only:
        protocol = json.loads((output / 'protocol.json').read_text(encoding='utf-8'))
        plan = json.loads((output / 'planned_cases.json').read_text(encoding='utf-8'))
        make_report(output, plan, protocol, args.previous_results)
        return 0
    modules = [s.strip() for s in args.modules.split(',')]
    require(set(modules) <= {'compare', 'uncertainty', 'external', 'report'} and len(set(modules)) == len(modules), 'Invalid or duplicate modules')
    require(set(modules) & {'compare', 'uncertainty', 'external'}, 'Use --report-only to report a previous run without new simulations')
    require(args.workers >= 1, 'workers must be positive')
    require(os.name != 'nt' or args.workers == 1, 'Windows testing requires --workers 1; parallel production uses Linux fork')
    require(.8 <= args.min_bootstrap_success <= 1, 'Bootstrap support threshold must be between 0.8 and 1')
    if not args.smoke:
        require(min(args.compare_replicates, args.uncertainty_replicates, args.external_replicates) >= 200,
                'Use --smoke for fewer than 200 outer repetitions')
        require(args.bootstrap_draws >= 199, 'Use --smoke for fewer than 199 bootstrap draws')
    settings = dict(profile='smoke' if args.smoke else 'full', n_grid=[20] if args.smoke else [20,80],
        compare_replicates=4 if args.smoke else args.compare_replicates,
        uncertainty_replicates=4 if args.smoke else args.uncertainty_replicates,
        external_replicates=4 if args.smoke else args.external_replicates,
        bootstrap_draws=19 if args.smoke else args.bootstrap_draws,
        min_bootstrap_success=args.min_bootstrap_success, nuclei=200, paired_seed=2026101103,
        bootstrap_seed=2026101117, external_seed=2026101119, reference_split=0,
        modules=modules, marker_overlap_min=.70, test_overlap_min=.80, external_min_cells_per_class=10,
        estimator_preprocessing='log2(CPM+1), reference-frozen markers, official RNA-seq default gamma',
        uncertainty='joint_shared_reference_donor_and_stratified_mixture_pairs_bootstrap;not_DECALS',
        interval='point_beta +/- t_0.975_df_nminus8 * bootstrap_SD;no_bias_correction',
        external_source=SOURCE, external_scope='new_resource_after_protocol_lock;not_AD_diagnosis_inference')
    cache = output / 'cache'
    cache.mkdir(exist_ok=True)
    roots = [p for p in [args.external_cache, root] if p is not None]
    status_path = output / 'RUN_STATUS.json'
    compatible_output = not (output / 'protocol.json').exists()
    try:
        r_info = check_r(args, cache, roots) if set(modules) & {'compare', 'external'} else {'status': 'not_requested'}
        folders, gene_map, identities = E.resolve_inputs(args)
        external_files = {}
        if 'external' in modules:
            external_files = {name: exact_cache_file(name, cache, roots, args.offline) for name in (META_NAME, COUNT_NAME)}
        versions = {name: importlib.metadata.version(name) for name in ('numpy','pandas','scipy','h5py','matplotlib')}
        body = dict(version=VERSION, settings=settings, engine_sha256=ENGINE_SHA256,
            script_sha256=sha(Path(__file__)), input_hashes={x['name']:x['sha256'] for x in identities},
            public_inputs={name:sha(path) for name, path in external_files.items()},
            official={k:v for k,v in r_info.items() if k not in ('library','executable')}, software=versions)
        signature = M.digest(body)
        protocol = dict(run_signature=signature, **body)
        protocol_path = output / 'protocol.json'
        if protocol_path.exists():
            require(json.loads(protocol_path.read_text(encoding='utf-8'))['run_signature'] == signature,
                    'Output already belongs to different code, settings, inputs or software. Choose a new --output; nothing is overwritten.')
        else:
            emit_json(protocol_path, dict(protocol, locked_utc=utc_now(),
                rule='Frozen before external outcome generation; not a public preregistration'))
        compatible_output = True
        emit_json(output / 'execution_environment.json', dict(python=platform.python_version(), platform=platform.platform(),
            workers=args.workers, official=r_info, inputs=identities, gpu_required=False))
        if args.preflight:
            emit_json(output / 'PREFLIGHT.json', dict(status='passed', simulations_run=False, run_signature=signature))
            print('PREFLIGHT PASS; no simulations run.', flush=True)
            return 0
        emit_json(status_path, dict(status='RUNNING', run_signature=signature, started_utc=utc_now()))
        sources, jobs = E.prepare_inputs(folders, gene_map)
        if 'external' in modules:
            external = read_external(external_files[COUNT_NAME], external_files[META_NAME],
                                     sources['LIBD']['genes'], output / 'external')
            jobs.extend(make_external_jobs(jobs, external, output))
        JOBS = jobs
        OPTIONS = dict(settings, official=r_info, output=str(output), run_signature=signature)
        plan = plan_cases(jobs, modules, OPTIONS)
        emit_json(output / 'planned_cases.json', plan)
        emit_csv(output / 'planned_cases.csv', plan)
        print('PLAN', len(plan), 'cases;', {m:sum(c['module']==m for c in plan) for m in modules}, flush=True)
        if args.workers == 1:
            for case in plan:
                run_case(case)
        else:
            with ProcessPoolExecutor(max_workers=args.workers, mp_context=multiprocessing.get_context('fork')) as pool:
                futures = {pool.submit(run_case, case):case for case in plan}
                for future in as_completed(futures):
                    future.result()
        previous = args.previous_results
        if previous is None and (root / 'paper3_innovation_results_v1' / 'RUN_STATUS.json').exists():
            previous = root / 'paper3_innovation_results_v1'
        report_status = make_report(output, plan, protocol, previous) if 'report' in modules else 'not_requested'
        status = 'COMPLETE_FOR_LOCKED_PLAN' if not args.smoke else 'SMOKE_COMPLETE_NOT_SCIENTIFIC_VALIDATION'
        emit_json(status_path, dict(status=status, run_signature=signature, planned_cases=len(plan),
            modules=modules, report=report_status, external_source=SOURCE if 'external' in modules else 'not_run',
            official_comparator='run' if set(modules)&{'compare','external'} else 'not_run',
            uncertainty_propagation='run' if set(modules)&{'uncertainty','external'} else 'not_run',
            DECALS='not_run;our_bootstrap_bridge_is_not_official_DECALS', finished_utc=utc_now()))
        print(status, output, flush=True)
        return 0
    except Exception as exc:
        failure_path = status_path if compatible_output else output / 'LAST_REJECTED_ATTEMPT.json'
        emit_json(failure_path, dict(status='FAILED_OR_BLOCKED', error=str(exc), traceback=traceback.format_exc(),
                                  completed_cases_preserved=True, updated_utc=utc_now()))
        traceback.print_exc()
        return 2


if __name__ == '__main__':
    raise SystemExit(main())
